code.source:
#include <iostream>
#include <memory>
using namespace std;

class Animal {
public:
    virtual void speak() const { cout << "..." << endl; }
    virtual ~Animal() = default;
};

class Dog : public Animal {
public:
    void speak() const override { cout << "Woof" << endl; }
};

int main() {
    unique_ptr<Animal> a = make_unique<Dog>();
    a->speak();
    return 0;
}

#include <iostream>
#include <memory>
#include <vector>
using namespace std;

class Animal {
public:
    virtual void speak() const = 0;
    virtual ~Animal() = default;
};

class Dog : public Animal {
public:
    void speak() const override { cout << "Woof" << endl; }
};

class Cat : public Animal {
public:
    void speak() const override { cout << "Meow" << endl; }
};

int main() {
    vector<unique_ptr<Animal>> zoo;
    zoo.push_back(make_unique<Dog>());
    zoo.push_back(make_unique<Cat>());
    for (const auto& a : zoo) {
        a->speak();
    }
    return 0;
}

